<?php
namespace App\Modules\Sales\Domain\Models;
use App\Models\User;use App\Modules\Inventory\Domain\Models\InventoryMovement;use App\Modules\Finance\Domain\Models\JournalEntry;use App\Modules\Orders\Domain\Models\SalesOrder;use App\Modules\People\Domain\Models\Person;use App\Modules\Pricing\Domain\Models\PriceList;use App\Modules\Sales\Domain\Enums\SaleStatus;use Illuminate\Database\Eloquent\Attributes\Fillable;use Illuminate\Database\Eloquent\Concerns\HasUlids;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;use Illuminate\Database\Eloquent\Relations\HasMany;use Illuminate\Database\Eloquent\Relations\HasOne;
#[Fillable(['document_number','customer_person_id','sales_order_id','sold_at','due_at','status','price_list_id','subtotal','discount','total','advance_applied','paid_amount','balance_amount','cost_of_goods_sold','gross_profit','payment_plan','inventory_movement_id','journal_entry_id','price_authorization_id','inventory_authorization_id','created_by','reversal_of_id','reversed_at','reversal_reason'])]
class Sale extends Model {use HasUlids;public function customer():BelongsTo{return $this->belongsTo(Person::class,'customer_person_id');}public function order():BelongsTo{return $this->belongsTo(SalesOrder::class,'sales_order_id');}public function priceList():BelongsTo{return $this->belongsTo(PriceList::class);}public function lines():HasMany{return $this->hasMany(SaleLine::class);}public function returns():HasMany{return $this->hasMany(SaleReturn::class);}public function receivable():HasOne{return $this->hasOne(Receivable::class,'source_id')->where('source_type',$this->getMorphClass());}public function inventoryMovement():BelongsTo{return $this->belongsTo(InventoryMovement::class);}public function journalEntry():BelongsTo{return $this->belongsTo(JournalEntry::class);}public function creator():BelongsTo{return $this->belongsTo(User::class,'created_by');}protected function casts():array{return ['sold_at'=>'datetime','due_at'=>'date','status'=>SaleStatus::class,'subtotal'=>'integer','discount'=>'integer','total'=>'integer','advance_applied'=>'integer','paid_amount'=>'integer','balance_amount'=>'integer','cost_of_goods_sold'=>'integer','gross_profit'=>'integer','payment_plan'=>'array','reversed_at'=>'datetime'];}}
